q=dict(question='Can VerifyLeader consume nonvoter acknowledgments as the quorum support used to confirm current leadership, and what voter-eligibility responsibility applies to that success?',importance='A false authority confirmation could undermine the API use of preventing stale FSM reads after leadership loss. The local counting discrepancy alone does not establish a stale read.',source_ids=['src-verify-contract','src-verify-start','src-verify-notify','src-verify-vote','src-verify-result','src-lease','src-config-types','src-replication-lifetime'],participants=['Leader','Configured voters','Configured nonvoter replication peer','VerifyLeader caller'],objects=['verifyFuture','replication notify maps','latest configuration'],contexts=['Stable mixed voter/nonvoter configuration','One active leader tenure and one verification request'],event_paths=['VerifyLeader -> verifyCh -> verifyLeader -> peer notify maps -> heartbeat/replication completion -> notifyAll -> verifyFuture.vote -> leaderLoop result'],activity_classes=['A2'],behavior_ids=['b-verify'],fact_ids=['f-verify-support'],supporting_behavior_ids={'b-membership':'Suffrage defines participants and threshold; replication includes nonvoters.','b-leader-context':'Lease and tenure cleanup independently limit stale authority.','b-append':'Actual follower response producer accepts a current-term heartbeat without voter-specific response filtering.'},obligation_relation_kind='consumption',counterevidence=['Lease checks explicitly count only voters and can independently terminate leadership.','A positive nonvoter response can accurately report that it recognizes the sender; it does not alone demonstrate another leader exists.','Commitment and elections already filter voter eligibility; this question is scoped to verification support.'],unknowns=['Precise source-backed requirement for voter-qualified VerifyLeader success, distinct from election and log commitment.','Legal history and schedule producing nonvoter-only additional support without a voter acknowledgment for this verification.','Whether an externally stale read follows in a legal history despite independent lease checks.'],priority=3,trigger_rationale='Unlike commitment.match and checkLeaderLease, verifyLeader registers with every replication peer, while quorumSize counts only voters and notifyAll carries no suffrage. Source contract/history work and a small accounting exploration can distinguish eligibility before a costly cluster endpoint test. The other known commit-bound lead has unresolved backtracking protection, making it a less direct first discriminator.',disposition='needs_specific_evidence',preferred_check='source_review')
